"use client";

import {
  useRef,
  useState,
  type ComponentProps,
  type KeyboardEvent,
} from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import Tooltip from "./toggle-group-utils/tooltip";

type IconType = ComponentProps<typeof HugeiconsIcon>["icon"];

export interface ToggleGroupItem {
  value: string;
  label: string;
  /** With an icon, the button shows only the icon and the label becomes its tooltip. */
  icon?: IconType;
  disabled?: boolean;
}

export interface ToggleGroupProps {
  /** Names the group for screen readers ("Text style"). */
  label: string;
  items: ToggleGroupItem[];
  /** The values switched on. */
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  size?: "sm" | "md";
}

// The one Tab stop: the last button used, else the first that can be used.
export default function ToggleGroup({
  label,
  items,
  value,
  defaultValue = [],
  onValueChange,
  size = "md",
}: ToggleGroupProps) {
  const [internalValue, setInternalValue] = useState<string[]>(defaultValue);
  const resolvedValue = value ?? internalValue;

  const barRef = useRef<HTMLDivElement>(null);
  const [current, setCurrent] = useState<string | undefined>(undefined);
  const stop = current ?? items.find((i) => !i.disabled)?.value;

  function toggle(v: string) {
    const next = resolvedValue.includes(v)
      ? resolvedValue.filter((x) => x !== v)
      : [...resolvedValue, v];
    if (!value) setInternalValue(next);
    onValueChange?.(next);
    setCurrent(v);
  }

  // Toolbar keys (WAI-ARIA): arrows move between buttons, mirrored right to left; Home/End jump.
  function onKeyDown(e: KeyboardEvent<HTMLDivElement>) {
    const bar = barRef.current;
    if (!bar) return;
    const buttons = [
      ...bar.querySelectorAll<HTMLButtonElement>("button:not(:disabled)"),
    ];
    const at = buttons.indexOf(document.activeElement as HTMLButtonElement);
    if (at < 0) return;
    const rtl = getComputedStyle(bar).direction === "rtl";
    const next: Record<string, number> = {
      ArrowRight: at + (rtl ? -1 : 1),
      ArrowLeft: at + (rtl ? 1 : -1),
      Home: 0,
      End: buttons.length - 1,
    };
    const n = next[e.key];
    if (n === undefined) return;
    e.preventDefault();
    const target = buttons[(n + buttons.length) % buttons.length];
    setCurrent(target.dataset.value);
    target.focus();
  }

  function renderButton(
    item: ToggleGroupItem,
    extra: Record<string, unknown> = {},
    reactKey?: string,
  ) {
    return (
      <button
        key={reactKey}
        type="button"
        className={["sina-toggle-group-item", size, item.icon ? "square" : ""]
          .filter(Boolean)
          .join(" ")}
        data-value={item.value}
        aria-pressed={resolvedValue.includes(item.value)}
        aria-label={
          item.icon && !extra["aria-labelledby"] ? item.label : undefined
        }
        tabIndex={item.value === stop ? 0 : -1}
        disabled={item.disabled}
        {...extra}
        onClick={() => toggle(item.value)}
      >
        {item.icon ? (
          <HugeiconsIcon
            icon={item.icon}
            size={size === "sm" ? 16 : 18}
            color="currentColor"
          />
        ) : (
          item.label
        )}
      </button>
    );
  }

  return (
    <div
      ref={barRef}
      role="toolbar"
      aria-label={label}
      className="sina-toggle-group"
      onKeyDown={onKeyDown}
    >
      {items.map((item) =>
        item.icon ? (
          <Tooltip key={item.value} text={item.label} labels>
            {(props) => renderButton(item, props)}
          </Tooltip>
        ) : (
          renderButton(item, {}, item.value)
        ),
      )}
    </div>
  );
}

