"use client";

import ToggleGroup from "@/components/ui/toggle-group";
import { useState } from "react";

export default function ToggleGroupLabelsDemo() {
  const [columns, setColumns] = useState<string[]>(["arabic", "latin"]);

  return (
    <div style={{ display: "grid", gap: "1rem", justifyItems: "start" }}>
      <ToggleGroup
        label="Columns to show"
        size="sm"
        value={columns}
        onValueChange={setColumns}
        items={[
          { value: "arabic", label: "Arabic" },
          { value: "latin", label: "Latin" },
          { value: "commentary", label: "Commentary" },
          { value: "facsimile", label: "Facsimile", disabled: true },
        ]}
      />
      <p style={{ margin: 0, color: "var(--ui-muted)", fontSize: "0.875rem" }}>
        Showing: {columns.length ? columns.join(", ") : "nothing"}
      </p>
    </div>
  );
}

